CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(120) PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id VARCHAR(80) PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id VARCHAR(120) PRIMARY KEY, category_id VARCHAR(80) NOT NULL REFERENCES categories(id) ON DELETE RESTRICT, name VARCHAR(180) NOT NULL, normalized_name VARCHAR(180) NOT NULL, description TEXT, price NUMERIC(10,2) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_normalized_name ON products(normalized_name);
CREATE TABLE IF NOT EXISTS inventory (product_id VARCHAR(120) PRIMARY KEY REFERENCES products(id) ON DELETE RESTRICT, digital_stock INT NOT NULL, physical_stock INT NOT NULL, reorder_point INT NOT NULL, average_sales NUMERIC(10,2) NOT NULL, last_physical_observation_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales (id VARCHAR(120) PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, total NUMERIC(10,2));
CREATE TABLE IF NOT EXISTS sale_items (id VARCHAR(140) PRIMARY KEY, sale_id VARCHAR(120) NOT NULL REFERENCES sales(id) ON DELETE RESTRICT, product_id VARCHAR(120) NOT NULL REFERENCES products(id) ON DELETE RESTRICT, quantity INT NOT NULL, unit_price NUMERIC(10,2) NOT NULL, subtotal NUMERIC(10,2) NOT NULL);
CREATE TABLE IF NOT EXISTS purchases (id VARCHAR(120) PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_items (id VARCHAR(140) PRIMARY KEY, purchase_id VARCHAR(120) NOT NULL REFERENCES purchases(id) ON DELETE RESTRICT, product_id VARCHAR(120) NOT NULL REFERENCES products(id) ON DELETE RESTRICT, quantity INT NOT NULL, unit_cost NUMERIC(10,2));
CREATE TABLE IF NOT EXISTS promotions (id VARCHAR(120) PRIMARY KEY, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, image_url VARCHAR(500), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS feedback (id VARCHAR(120) PRIMARY KEY, rating SMALLINT NOT NULL, comment VARCHAR(500) NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS edge_observations (id BIGSERIAL PRIMARY KEY, observation_id VARCHAR(180) NOT NULL UNIQUE, zone_id VARCHAR(120) NOT NULL, source_id VARCHAR(120) NOT NULL, observed_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS edge_observation_items (id BIGSERIAL PRIMARY KEY, edge_observation_id BIGINT NOT NULL REFERENCES edge_observations(id) ON DELETE RESTRICT, product_id VARCHAR(120) NOT NULL REFERENCES products(id) ON DELETE RESTRICT, quantity INT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_edge_observations_observed_at ON edge_observations(observed_at);
